message.content:
{
  "definition_simple": "中身が何もなく、からっぽになっている穴やくぼみのこと。",
  "definition_standard": "物体の内部がからになっていること。また、そのからっぽの空間や穴。転じて、内容や実質が失われて形骸化している状態。",
  "pos": "名詞",
  "semantic_class": "concrete",
  "sentences": [
    {
      "tier": "T1",
      "japanese": "木の幹に大きな空洞がある。",
      "english": "There is a large hollow in the tree trunk."
    },
    {
      "tier": "T2",
      "japanese": "地面の下に空洞が見つかった。",
      "english": "A cavity was found beneath the ground."
    },
    {
      "tier": "T2",
      "japanese": "この壁の裏には空洞ができている。",
      "english": "A hollow space has formed behind this wall."
    },
    {
      "tier": "T3",
      "japanese": "古い大木の空洞に小鳥が巣を作っている。",
      "english": "Small birds are nesting in the hollow of an old large tree."
    },
    {
      "tier": "T3",
      "japanese": "道路が突然陥没し、地下に巨大な空洞が広がっていることが判明した。",
      "english": "The road suddenly caved in, revealing a massive underground cavity."
    },
    {
      "tier": "T4",
      "japanese": "産業の空洞化が進むと、地域の雇用が急激に失われる。",
      "english": "As the hollowing out of industry progresses, regional employment is sharply lost."
    },
    {
      "tier": "T4",
      "japanese": "レントゲン検査によって骨の内部に小さな空洞が確認された。",
      "english": "An X-ray examination confirmed a small cavity inside the bone."
    },
    {
      "tier": "T5",
      "japanese": "形式的な手続きばかりが先行し、議論の実質的な空洞化を招いている。",
      "english": "Formal procedures precede substance, leading to an effective hollowing out of the debate."
    },
    {
      "tier": "T5",
      "japanese": "鍾乳洞の奥深くには、何万年もの歳月をかけて形成された神秘的な空洞が連なっている。",
      "english": "Deep within the limestone cave lies a series of mystical caverns formed over tens of thousands of years."
    },
    {
      "tier": "T6",
      "japanese": "度重なる組織改革の失敗により、中核を担う人材が流出して組織内部に回復不能な空洞が生じた。",
      "english": "Due to repeated failures in organizational reform, core personnel fled, leaving an irreparable void within the organization."
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "primary_collocate": "空洞化",
  "collocation_distractors": [
    {
      "word": "空白",
      "reason": "「空白」は埋めるべき空所や時間的途切れを表す名詞であり、物理的な空洞や構造的空洞化を示す「空洞」と慣用的な連語を形成しない。"
    },
    {
      "word": "虚無",
      "reason": "「虚無」は哲学・心理的な虚しさを表す抽象名詞であり、物理的・機能的空隙を指す「空洞」の修飾・複合語として定着していない。"
    },
    {
      "word": "隙間",
      "reason": "「隙間」は物と物の間の狭い空隙を指す名詞であり、中身が抜けた内部空間を表す「空洞」とは共起構造が重複し不自然である。"
    }
  ],
  "collocation_wrong_collocate": "空洞現象",
  "cloze_distractors": [
    {
      "word": "隙間",
      "reason": "「隙間」は物と物の間の細いあき間を指すため、幹の内部がまるごとえぐれて空間になっている状態には適さない。"
    },
    {
      "word": "空間",
      "reason": "「空間」は物理的なスペース全般を指す広範な概念語であり、木の内部にできた穴そのものを具体的に指す語として不自然。"
    },
    {
      "word": "虚空",
      "reason": "「虚空」は何もない大空や空中を指す文学的・仏教的語彙であり、物体の内部のからっぽな穴を表す文脈には使えない。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "japanese": "彼は空洞な性格なので、誰とでもすぐに仲良くなれる。",
      "reason": "形容動詞「空洞な」として人の性格を肯定的に修飾する用法は存在せず、「気さくな」や「素直な」との混同。"
    },
    {
      "japanese": "コップの水を全部飲んで、中を空洞にした。",
      "reason": "容器の液体をなくすことは「空（から）にする」と言い、構造内部がえぐれて穴になっているわけではないため「空洞にする」とは言わない。"
    },
    {
      "japanese": "部屋が狭いので、もっと空洞を広げてください。",
      "reason": "居住空間や余白を広げる文脈で「空洞」は用いず、「スペース」や「部屋の広さ」を用いるべき誤用。"
    }
  ],
  "spot_incorrect": {
    "sentence": "激しい雨で地盤が緩み、アスファルトの下に深い空洞が落ちた。",
    "error_description": "「空洞」は穴や空間そのものを指すため「落ちる」という述語とは共起せず、「空洞ができた」または「地面が落ちた（陥没した）」とする必要がある。",
    "corrected_sentence": "激しい雨で地盤が緩み、アスファルトの下に深い空洞ができた。"
  },
  "word_family_forms": [
    "空洞化",
    "空洞化する"
  ],
  "word_family_fake_forms": [
    "空洞的",
    "空洞さ",
    "空洞がる"
  ],
  "syn_ant_candidates": [
    {
      "word": "うろ",
      "type": "synonym"
    },
    {
      "word": "空隙",
      "type": "synonym"
    },
    {
      "word": "洞穴",
      "type": "synonym"
    },
    {
      "word": "充実",
      "type": "antonym"
    }
  ],
  "particle_candidates": [
    {
      "particle": "に",
      "is_correct": true,
      "explanation": "存在場所（木の幹の中）を示す助詞として「に」が文法的に正しい。"
    },
    {
      "particle": "で",
      "is_correct": false,
      "explanation": "「で」は動作の行われる場所を示す助詞であり、静的な存在を表す述語「ある」とは共起しない。"
    },
    {
      "particle": "を",
      "is_correct": false,
      "explanation": "「を」は他動詞の目的語を示す助詞であり、自動詞「ある」の場所補語には使えない。"
    },
    {
      "particle": "へ",
      "is_correct": false,
      "explanation": "「へ」は移動の方向・帰着点を示す助詞であり、存在の所在を示す文脈には適さない。"
    }
  ]
}
